private void on_trigger_enter(Collider other)
{
    if (other.CompareTag("GamePiece"))
    {
        bool wasLegal = false;
        if (other.TryGetComponent<ShotData>(out ShotData shotData))
        {
            wasLegal = shotData.wasShotFromLegalZone;
        }

        if (hub != null)
        {
            hub.countFuel(wasLegal);
        }
    }
}
